// A pi-durable Storage that keeps its log as a chain of git commits on one ref.
//
// Like the JSONL backend, the state lives in a MemoryStorage; every stored batch is one git commit whose tree holds
// `batch.json` ({ format, seq, writes }), parented on the previous batch. Opening replays the chain from its root.
// The ref moves by compare-and-swap, so a second writer on the same ref fails instead of forking the log.
import type { Context } from "@earendil-works/chord/context";
import {
	type ConversationId,
	type EntryId,
	type Id,
	MemoryStorage,
	type Seq,
	type Storage,
	type StorageWrite,
} from "@earendil-works/pi-durable";

import { GitRepo, type Signature } from "./git.ts";

const FORMAT_VERSION = 1;
const BATCH_FILE = "batch.json";
const DEFAULT_AUTHOR: Signature = {
	name: "pi-durable",
	email: "pi-durable@localhost",
};

export interface GitStorageOptions {
	/** A work tree, `.git` dir, or bare repository. It must exist. */
	readonly repo: string;
	/** The ref holding the log, e.g. `refs/pi/threads/42`. */
	readonly ref: string;
	/** Commit author and committer. */
	readonly author?: Signature;
	/**
	 * Called after each stored commit() with the new tip and the batches it added, e.g. to push at turn boundaries
	 * (see `isTurnBoundary`). Must not throw; errors are swallowed.
	 */
	readonly onCommit?: (event: CommitEvent) => void;
}

interface CommitEvent {
	readonly tip: string;
	readonly batches: readonly Batch[];
}

export interface Batch {
	readonly format: number;
	readonly seq: number;
	readonly writes: readonly StorageWrite[];
}

class GitStorageCorruptionError extends Error {
	constructor(message: string, options?: { cause?: unknown }) {
		super(message, options);
		this.name = "GitStorageCorruptionError";
	}
}
export class GitStoragePoisonedError extends Error {
	constructor(cause: unknown) {
		super("Git storage is poisoned and must be reopened", { cause });
		this.name = "GitStoragePoisonedError";
	}
}

export class GitStorage implements Storage {
	readonly repo: GitRepo;
	readonly ref: string;
	private readonly author: Signature;
	private readonly onCommit: GitStorageOptions["onCommit"];
	private readonly memory = new MemoryStorage();
	private head: string | undefined;
	private closed = false;
	private poisonError: GitStoragePoisonedError | undefined;
	/** Settles once the batches being written are; memory is ahead of the ref meanwhile. */
	private writing: Promise<void> | undefined;
	/** Serializes commit() calls. */
	private queue: Promise<void> = Promise.resolve();

	private constructor(repo: GitRepo, options: GitStorageOptions) {
		this.repo = repo;
		this.ref = options.ref;
		this.author = options.author ?? DEFAULT_AUTHOR;
		this.onCommit = options.onCommit;
	}

	static async open(options: GitStorageOptions): Promise<GitStorage> {
		const repo = await GitRepo.open(options.repo);
		const storage = new GitStorage(repo, options);
		try {
			await storage.recover();
		} catch (error) {
			await repo.close();
			throw error;
		}
		return storage;
	}

	/** The commit the ref points at, as of the last commit or open; undefined while empty. */
	get tip(): string | undefined {
		return this.head;
	}

	private async recover(): Promise<void> {
		const tip = await this.repo.readRef(this.ref);
		this.head = tip;
		if (tip === undefined) {
			return;
		}
		const chain = await this.repo.commits(tip);
		const merge = chain.find((commit) => commit.parents.length > 1);
		if (merge) {
			throw new GitStorageCorruptionError(
				`Merge commit ${merge.id} in ${this.ref}`,
			);
		}
		// All reads go to one cat-file process, which pipelines them.
		const batches = await Promise.all(
			chain.map(async ({ id: sha }) => {
				const content = await this.repo
					.readFile(sha, BATCH_FILE)
					.catch((error: unknown) => {
						throw new GitStorageCorruptionError(
							`Commit ${sha} has no ${BATCH_FILE}`,
							{ cause: error },
						);
					});
				let batch: unknown;
				try {
					batch = JSON.parse(content.toString("utf8"));
				} catch (error) {
					throw new GitStorageCorruptionError(
						`Malformed ${BATCH_FILE} in ${sha}`,
						{ cause: error },
					);
				}
				if (!isBatch(batch)) {
					throw new GitStorageCorruptionError(
						`Unsupported or invalid batch in ${sha}`,
					);
				}
				return { sha, batch };
			}),
		);
		for (const { sha, batch } of batches) {
			try {
				// oxlint-disable-next-line typescript/no-unsafe-type-assertion -- Seq is a branded number; the log is where seqs come from
				this.memory.prepareCommit(batch.writes, batch.seq as Seq).apply();
			} catch (error) {
				throw new GitStorageCorruptionError(
					`Invalid committed state at seq ${batch.seq} (${sha})`,
					{ cause: error },
				);
			}
		}
	}

	async commit(
		batches: readonly (readonly StorageWrite[])[],
		receive: (index: number, seq: Seq) => void,
		context: Context,
	): ReturnType<Storage["commit"]> {
		this.assertUsable();
		const previous = this.queue;
		const turn = Promise.withResolvers<undefined>();
		this.queue = turn.promise;
		await previous;
		const writing = Promise.withResolvers<undefined>();
		this.writing = writing.promise;
		const seqs: Seq[] = [];
		const encoded: Batch[] = [];
		let refused: { error: unknown } | undefined;
		try {
			this.assertUsable();
			for (const writes of batches) {
				let prepared: ReturnType<MemoryStorage["prepareCommit"]>;
				try {
					prepared = this.memory.prepareCommit(writes);
				} catch (error) {
					refused = { error };
					break;
				}
				encoded.push({
					format: FORMAT_VERSION,
					seq: prepared.seq,
					writes: prepared.writes,
				});
				seqs.push(prepared.apply());
			}
			if (encoded.length > 0) {
				await this.persist(encoded, context);
			}
		} catch (error) {
			// Memory ran ahead of the ref: once a batch applied, any failure poisons the storage.
			if (seqs.length === 0) {
				throw error;
			}
			throw this.poison(error);
		} finally {
			this.writing = undefined;
			writing.resolve(undefined);
			turn.resolve(undefined);
		}
		for (const [index, seq] of seqs.entries()) {
			receive(index, seq);
		}
		if (
			encoded.length > 0 &&
			this.head !== undefined &&
			this.onCommit !== undefined
		) {
			try {
				this.onCommit({ tip: this.head, batches: encoded });
			} catch {
				// observers never fail a commit
			}
		}
		return refused === undefined
			? { stored: seqs.length }
			: { stored: seqs.length, refused: refused.error };
	}

	private async persist(
		batches: readonly Batch[],
		_context: Context,
	): Promise<void> {
		let parent = this.head;
		// Each commit is the parent of the next, so the writes are sequential.
		/* oxlint-disable eslint/no-await-in-loop */
		for (const batch of batches) {
			const blob = await this.repo.writeBlob(JSON.stringify(batch));
			const tree = await this.repo.writeTree({ [BATCH_FILE]: blob });
			parent = await this.repo.writeCommit({
				tree,
				parents: parent === undefined ? [] : [parent],
				author: this.author,
				message: commitMessage(batch),
			});
		}
		/* oxlint-enable eslint/no-await-in-loop */
		if (parent === undefined) {
			return;
		}
		await this.repo.updateRef(this.ref, parent, this.head);
		this.head = parent;
	}

	async mintId<I extends Id<string>>(): Promise<I> {
		return this.store.mintId<I>();
	}
	async conversation(
		...args: Parameters<Storage["conversation"]>
	): ReturnType<Storage["conversation"]> {
		return (await this.readable()).conversation(...args);
	}
	async scanConversations(
		...args: Parameters<Storage["scanConversations"]>
	): ReturnType<Storage["scanConversations"]> {
		return (await this.readable()).scanConversations(...args);
	}
	entry(id: EntryId, context: Context): ReturnType<MemoryStorage["entry"]>;
	entry(
		conversationId: ConversationId,
		id: EntryId,
		context: Context,
	): ReturnType<MemoryStorage["entry"]>;
	async entry(
		idOrConversation: EntryId | ConversationId,
		idOrContext: EntryId | Context,
		context?: Context,
	): ReturnType<MemoryStorage["entry"]> {
		const memory = await this.readable();
		/* oxlint-disable typescript/no-unsafe-type-assertion -- the overloads differ by arity, so the third argument tells which one the caller used */
		return context === undefined
			? memory.entry(idOrConversation as EntryId, idOrContext as Context)
			: memory.entry(
					idOrConversation as ConversationId,
					idOrContext as EntryId,
					context,
				);
		/* oxlint-enable typescript/no-unsafe-type-assertion */
	}
	async findLatestHeadMarker(
		...args: Parameters<Storage["findLatestHeadMarker"]>
	): ReturnType<Storage["findLatestHeadMarker"]> {
		return (await this.readable()).findLatestHeadMarker(...args);
	}
	async scanEntries(
		...args: Parameters<Storage["scanEntries"]>
	): ReturnType<Storage["scanEntries"]> {
		return (await this.readable()).scanEntries(...args);
	}
	async task(
		...args: Parameters<Storage["task"]>
	): ReturnType<Storage["task"]> {
		return (await this.readable()).task(...args);
	}
	async scanTasks(
		...args: Parameters<Storage["scanTasks"]>
	): ReturnType<Storage["scanTasks"]> {
		return (await this.readable()).scanTasks(...args);
	}
	async submission(
		...args: Parameters<Storage["submission"]>
	): ReturnType<Storage["submission"]> {
		return (await this.readable()).submission(...args);
	}
	async scanSubmissions(
		...args: Parameters<Storage["scanSubmissions"]>
	): ReturnType<Storage["scanSubmissions"]> {
		return (await this.readable()).scanSubmissions(...args);
	}
	async submissionByRequest(
		...args: Parameters<Storage["submissionByRequest"]>
	): ReturnType<Storage["submissionByRequest"]> {
		return (await this.readable()).submissionByRequest(...args);
	}
	async findDocument(
		...args: Parameters<Storage["findDocument"]>
	): ReturnType<Storage["findDocument"]> {
		return (await this.readable()).findDocument(...args);
	}
	async document(
		...args: Parameters<Storage["document"]>
	): ReturnType<Storage["document"]> {
		return (await this.readable()).document(...args);
	}
	async scanDocuments(
		...args: Parameters<Storage["scanDocuments"]>
	): ReturnType<Storage["scanDocuments"]> {
		return (await this.readable()).scanDocuments(...args);
	}

	async close(context: Context): Promise<void> {
		if (this.closed) {
			return;
		}
		this.closed = true;
		await this.queue;
		await this.memory.close(context);
		await this.repo.close();
	}

	private get store(): MemoryStorage {
		this.assertUsable();
		return this.memory;
	}
	private async readable(): Promise<MemoryStorage> {
		while (this.writing !== undefined) {
			// oxlint-disable-next-line eslint/no-await-in-loop -- a new write may start while we wait
			await this.writing;
		}
		return this.store;
	}
	private poison(cause: unknown): GitStoragePoisonedError {
		this.poisonError ??= new GitStoragePoisonedError(cause);
		return this.poisonError;
	}
	private assertUsable(): void {
		if (this.closed) {
			throw new Error("GitStorage is closed");
		}
		if (this.poisonError !== undefined) {
			throw this.poisonError;
		}
	}
}

function isBatch(value: unknown): value is Batch {
	if (typeof value !== "object" || value === null) {
		return false;
	}
	return (
		Reflect.get(value, "format") === FORMAT_VERSION &&
		Number.isSafeInteger(Reflect.get(value, "seq")) &&
		Array.isArray(Reflect.get(value, "writes"))
	);
}

/** `pi-durable: seq 12 (entry, task×2)` plus trailers, so `git log` reads well. */
function commitMessage(batch: Batch): string {
	const counts = new Map<string, number>();
	for (const write of batch.writes) {
		counts.set(write.type, (counts.get(write.type) ?? 0) + 1);
	}
	const summary = [...counts]
		.map(([type, n]) => (n === 1 ? type : `${type}×${n}`))
		.join(", ");
	return `pi-durable: seq ${batch.seq} (${summary})\n\nPi-Durable-Format: ${batch.format}\nPi-Durable-Seq: ${batch.seq}\n`;
}
import { setTimeout as sleep } from "node:timers/promises";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import type { Submission } from "@earendil-works/pi-durable";

import { ANSWER_KIND } from "./answers.ts";
import type { Thread } from "./thread.ts";
import type { Trigger } from "./triggers.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type SettledRecord = Awaited<ReturnType<Submission["wait"]>>;

export type ThreadResult =
	| { success: true; response: string }
	| { success: false; error: string };

export interface ConversationOptions {
	thread: Thread;
	log: Log;
	timeoutSeconds: number;
	pollIntervalMs: number;
	/** The message to submit for a trigger; `first` is true for the first one of a new thread. */
	message: (trigger: Trigger, first: boolean) => Promise<string>;
	/**
	 * Deliver a result. `alreadyPosted` is set when an earlier run delivered this answer (the trigger was
	 * answered together with another one). Returns where it was posted, recorded so it is never posted twice.
	 */
	deliver: (
		trigger: Trigger,
		result: ThreadResult,
		alreadyPosted: boolean,
	) => Promise<string | undefined>;
	/** Triggers that arrived since the run started; omitted for one-off runs. */
	poll?: () => Promise<Trigger[]>;
	/** The URLs of the questions pi-durable extensions asked in this run so far (see github-ui.ts). */
	asked?: () => readonly string[];
}

const EMPTY_RESPONSE = "Agent returned empty response";
const SUMMARY_SUFFIX = "-summary";
const SUMMARY_PROMPT = `IMPORTANT: You completed your work but did not provide a final text summary. This summary is REQUIRED. Please now write a plain-text summary of what you accomplished, including:
- What changes were made and why
- Which files were modified
- Any errors encountered or remaining issues
- Confirmation that your work is complete

Do NOT call any tools - just provide the text summary.`;

function describeUnanswered(
	record: SettledRecord,
	timedOutAfter: number | undefined,
): string {
	if (record.reason === "aborted" && timedOutAfter !== undefined) {
		return `Timeout after ${timedOutAfter} seconds`;
	}
	if (record.detail === undefined) {
		return record.reason ?? "unanswered";
	}
	const detail =
		typeof record.detail === "string"
			? record.detail
			: JSON.stringify(record.detail);
	return `${record.reason}: ${detail}`;
}

/**
 * Drives a thread through a set of triggers: submits them (new ones join the running conversation), waits for
 * every answer within the timeout, and delivers each answer or failure exactly once.
 */
export class ThreadConversation {
	private readonly handled = new Set<string>();
	private readonly pending = new Set<Promise<void>>();
	private delivering: Promise<void> = Promise.resolve();
	private posted = new Map<string, string>();
	private timedOut = false;
	private readonly options: ConversationOptions;

	constructor(options: ConversationOptions) {
		this.options = options;
	}

	async run(initial: Trigger[]): Promise<void> {
		const { thread, log, timeoutSeconds, pollIntervalMs, poll } = this.options;
		this.posted = await thread.postedResults();
		await this.submitAll(initial);

		const deadline = Date.now() + timeoutSeconds * 1000;
		for (;;) {
			const remaining = deadline - Date.now();
			if (remaining <= 0) {
				this.timedOut = true;
				break;
			}
			if (this.pending.size > 0) {
				const wait = new AbortController();
				const timer = sleep(Math.min(pollIntervalMs, remaining), undefined, {
					signal: wait.signal,
				}).catch(() => undefined);
				// oxlint-disable-next-line eslint/no-await-in-loop -- the poll loop waits between rounds by design
				await Promise.race([Promise.allSettled(this.pending), timer]);
				wait.abort();
			}
			const fresh = poll
				? // oxlint-disable-next-line eslint/no-await-in-loop -- each round polls once, after the wait
					(await poll()).filter((trigger) => !this.handled.has(trigger.key))
				: [];
			if (fresh.length > 0) {
				log.info(
					`${fresh.length} new comment(s) for pi; adding them to the conversation`,
				);
				// oxlint-disable-next-line eslint/no-await-in-loop -- new comments join before the next round
				await this.submitAll(fresh);
			} else if (this.pending.size === 0) {
				break;
			}
		}

		if (this.timedOut) {
			log.warning(`Timeout after ${timeoutSeconds} seconds; aborting the run`);
			await thread.abort();
		}
		await Promise.allSettled(this.pending);
		await this.delivering;
	}

	private async submitAll(triggers: Trigger[]): Promise<void> {
		for (const trigger of triggers) {
			if (!this.handled.has(trigger.key)) {
				const first = this.options.thread.isNew && this.handled.size === 0;
				this.handled.add(trigger.key);
				// oxlint-disable-next-line eslint/no-await-in-loop -- triggers are submitted in order
				const content = await this.options.message(trigger, first);
				this.track(trigger, this.answer(trigger, content));
			}
		}
	}

	private track(trigger: Trigger, result: Promise<SettledResult>): void {
		const settled = (async () => {
			try {
				this.enqueueDelivery(trigger, await result);
			} catch (error) {
				this.options.log.warning(getErrorMessage(error));
			}
		})();
		this.pending.add(settled);
		settled
			.finally(() => {
				this.pending.delete(settled);
			})
			.catch(() => undefined);
	}

	/** Submit and wait; an empty answer is followed by one request for a summary (as pi-action always did). */
	private async answer(
		trigger: Trigger,
		content: string,
	): Promise<SettledResult> {
		const outcome = await this.submitAndWait(trigger, trigger.key, content);
		// An answer an earlier run delivered (or a question it is waiting on) is not asked for again.
		if (!(outcome.empty && !this.timedOut) || this.posted.has(outcome.key)) {
			return outcome;
		}
		this.options.log.warning(
			"Agent returned empty response from first attempt. Re-prompting for a summary.",
		);
		const retry = await this.submitAndWait(
			trigger,
			`${trigger.key}${SUMMARY_SUFFIX}`,
			SUMMARY_PROMPT,
		);
		if (!retry.empty) {
			return retry;
		}
		return {
			key: retry.key,
			empty: true,
			result: {
				success: false,
				error: `Agent failed to provide a response after two attempts. First attempt: ${EMPTY_RESPONSE}. Retry attempt: ${EMPTY_RESPONSE}.`,
			},
		};
	}

	private async submitAndWait(
		trigger: Trigger,
		key: string,
		content: string,
	): Promise<SettledResult> {
		const asked = this.options.asked ?? (() => []);
		const askedBefore = asked().length;
		const { answer } = trigger;
		const submission = await this.options.thread.submit({
			key,
			content,
			data: {
				author: trigger.author.login,
				source: trigger.source,
				...(trigger.url ? { url: trigger.url } : {}),
			},
			...(answer
				? {
						entry: {
							kind: ANSWER_KIND,
							data: {
								key: answer.key,
								kind: answer.kind,
								answer: answer.answer,
								by: answer.by,
								url: answer.url,
							},
						},
					}
				: {}),
		});
		const record = await submission.wait(BACKGROUND_CONTEXT);
		if (record.status === "done" && record.answer !== undefined) {
			const { text, toolCalls } = await this.options.thread.answerText(
				record.answer,
			);
			const questions = asked().slice(askedBefore);
			if (toolCalls && questions.length > 0) {
				// The run ended on a question (its tool round asked to terminate): the answer comes in a later run.
				return {
					key: `answer-${record.answer}`,
					empty: false,
					waiting: questions,
					result: { success: true, response: text },
				};
			}
			return {
				key: `answer-${record.answer}`,
				empty: text === "",
				result: text
					? { success: true, response: text }
					: { success: false, error: EMPTY_RESPONSE },
			};
		}
		const timedOutAfter = this.timedOut
			? this.options.timeoutSeconds
			: undefined;
		return {
			key: `error-${record.id}`,
			empty: false,
			result: {
				success: false,
				error: describeUnanswered(record, timedOutAfter),
			},
		};
	}

	private enqueueDelivery(trigger: Trigger, outcome: SettledResult): void {
		this.delivering = this.delivering
			.then(async () => this.deliver(trigger, outcome))
			.catch((error: unknown) => {
				this.options.log.warning(
					`Failed to deliver result: ${getErrorMessage(error)}`,
				);
			});
	}

	private async deliver(
		trigger: Trigger,
		outcome: SettledResult,
	): Promise<void> {
		const alreadyPosted = this.posted.has(outcome.key);
		if (outcome.waiting) {
			this.options.log.info(
				`pi asked a question and ended its turn; waiting for an answer to ${outcome.waiting.join(", ")}`,
			);
			if (!alreadyPosted) {
				this.posted.set(outcome.key, outcome.waiting[0] ?? "");
				await this.options.thread.markPosted(
					outcome.key,
					outcome.waiting[0] ?? "",
				);
			}
			return;
		}
		if (alreadyPosted && !outcome.result.success) {
			return; // a failure an earlier run already reported
		}
		const url = await this.options.deliver(
			trigger,
			outcome.result,
			alreadyPosted,
		);
		if (url !== undefined && !alreadyPosted) {
			this.posted.set(outcome.key, url);
			await this.options.thread.markPosted(outcome.key, url);
		}
	}
}

interface SettledResult {
	/** `answer-<entryId>` or `error-<submissionId>`: what is delivered once. */
	key: string;
	empty: boolean;
	result: ThreadResult;
	/** The run ended on these questions: nothing is posted, the answers start a later run. */
	waiting?: readonly string[];
}
name: 'pi-action'
description: 'Run a durable pi coding agent on GitHub issues and PRs: one conversation per thread, stored in git'
author: 'Carlos Villela'
branding:
  icon: 'cpu'
  color: 'purple'

inputs:
  github_token:
    description: 'GitHub token for API access (issues, PRs, reactions, comments)'
    required: true
  api_key:
    description: 'LLM provider API key (runtime-only; alternatively set provider-specific env vars like ANTHROPIC_API_KEY)'
    required: false
  trigger_phrase:
    description: 'Phrase to trigger pi (e.g., @pi)'
    default: '@pi'
  allowed_bots:
    description: 'Comma-separated list of allowed bot usernames'
    default: ''
  allowed_users:
    description: 'Comma-separated GitHub usernames allowed to trigger pi. If set, users must be in this list.'
    default: ''
  allowed_associations:
    description: 'Comma-separated GitHub author associations allowed to trigger pi when allowed_users is empty'
    default: 'OWNER,MEMBER'
  timeout:
    description: 'Seconds before the run is aborted (its thread is still saved)'
    default: '1800'
  poll_interval:
    description: 'Seconds between checks for new comments while pi works; new trigger comments join the running conversation'
    default: '15'
  provider:
    description: 'LLM provider (anthropic, openai, google, etc.)'
    default: 'anthropic'
  model:
    description: 'Model ID'
    default: 'claude-sonnet-5-5'
  provider_base_url:
    description: 'Base URL for a single custom provider/model (e.g., https://inference-api.nvidia.com)'
    required: false
  provider_api:
    description: 'API type for the custom provider/model'
    required: false
    default: 'openai-completions'
  provider_api_key:
    description: 'Provider apiKey config value for custom providers; can be a literal key or env var name'
    required: false
  provider_auth_header:
    description: 'Add Authorization: Bearer <key> for custom provider requests'
    required: false
    default: 'false'
  model_name:
    description: 'Display name for the custom model'
    required: false
  model_reasoning:
    description: 'Whether the custom model supports reasoning/thinking'
    required: false
    default: 'false'
  model_input:
    description: 'Comma-separated custom model input modalities (text or text,image)'
    required: false
    default: 'text'
  model_context_window:
    description: 'Context window tokens for the custom model'
    required: false
    default: '128000'
  model_max_tokens:
    description: 'Max output tokens for the custom model'
    required: false
    default: '16384'
  compat_supports_developer_role:
    description: 'Whether the OpenAI-compatible custom provider supports developer role messages'
    required: false
  compat_supports_reasoning_effort:
    description: 'Whether the OpenAI-compatible custom provider supports reasoning_effort'
    required: false
  compat_force_adaptive_thinking:
    description: 'Use adaptive thinking for an Anthropic-compatible custom model (required by Claude Opus 4.6+ and Sonnet 4.6+)'
    required: false
  extensions:
    description: 'pi extensions to load: npm package specs or paths relative to the workspace, one per line or comma-separated. pi extensions contribute the model providers they register; packages with a pi-durable extension (pi.durable in package.json) add their tools to the conversation. npm packages are installed into a temp directory without lifecycle scripts. Extensions run inside the action with the job''s permissions and environment.'
    required: false
    default: ''
  trust_project:
    description: 'Let pi-durable extensions trust the repository: load and run its own configuration (such as .pi/ files). Only for repositories whose code you would run anyway; anyone who can open a PR can change those files.'
    required: false
    default: 'false'
  agent_dir:
    description: 'Agent directory (user-level state) for pi-durable extensions, relative to the workspace; a fresh temp directory under RUNNER_TEMP when empty'
    required: false
    default: ''
  prompt_template:
    description: 'Custom prompt template with placeholder variables'
    required: false
  output_mode:
    description: 'How to deliver results: comment (post to issue/PR) or output (set action outputs only)'
    required: false
    default: 'comment'
  prompt:
    description: 'Direct prompt for the agent (requires output_mode: output when no issue/PR context is available)'
    required: false
    default: ''
  pr_number:
    description: 'Pull request number to load explicitly (useful for workflow_dispatch)'
    required: false
    default: ''

outputs:
  response:
    description: 'The agent response text when output_mode is output'
    value: ${{ steps.run-pi-action.outputs.response }}
  success:
    description: 'Whether the agent succeeded (true/false) when output_mode is output'
    value: ${{ steps.run-pi-action.outputs.success }}

runs:
  using: 'composite'
  steps:
    # pi-action runs its TypeScript directly, which needs Node.js 24. Reuse the job's Node when it is new enough;
    # otherwise set it up (from the runner's tool cache, so this is quick).
    - name: Check Node.js version
      id: node
      shell: bash
      run: |
        if node -e 'process.exit(Number(process.versions.node.split(".")[0]) >= 24 ? 0 : 1)' 2>/dev/null; then
          echo "ok=true" >> "$GITHUB_OUTPUT"
        else
          echo "ok=false" >> "$GITHUB_OUTPUT"
        fi

    - name: Set up Node.js
      if: steps.node.outputs.ok != 'true'
      uses: actions/setup-node@v6
      with:
        node-version: '24'

    - name: Install action dependencies
      shell: bash
      run: npm ci --omit=dev --ignore-scripts --no-audit --no-fund --prefix ${{ github.action_path }}

    - name: Install pi-agent git hooks
      shell: bash
      run: node ${{ github.action_path }}/scripts/install-agent-hooks.js

    - name: Run pi-action
      id: run-pi-action
      shell: bash
      run: node --disable-warning=ExperimentalWarning ${{ github.action_path }}/src/index.ts
      env:
        INPUT_GITHUB_TOKEN: ${{ inputs.github_token }}
        INPUT_API_KEY: ${{ inputs.api_key }}
        INPUT_TRIGGER_PHRASE: ${{ inputs.trigger_phrase }}
        INPUT_ALLOWED_BOTS: ${{ inputs.allowed_bots }}
        INPUT_ALLOWED_USERS: ${{ inputs.allowed_users }}
        INPUT_ALLOWED_ASSOCIATIONS: ${{ inputs.allowed_associations }}
        INPUT_TIMEOUT: ${{ inputs.timeout }}
        INPUT_POLL_INTERVAL: ${{ inputs.poll_interval }}
        INPUT_PROVIDER: ${{ inputs.provider }}
        INPUT_MODEL: ${{ inputs.model }}
        INPUT_PROVIDER_BASE_URL: ${{ inputs.provider_base_url }}
        INPUT_PROVIDER_API: ${{ inputs.provider_api }}
        INPUT_PROVIDER_API_KEY: ${{ inputs.provider_api_key }}
        INPUT_PROVIDER_AUTH_HEADER: ${{ inputs.provider_auth_header }}
        INPUT_MODEL_NAME: ${{ inputs.model_name }}
        INPUT_MODEL_REASONING: ${{ inputs.model_reasoning }}
        INPUT_MODEL_INPUT: ${{ inputs.model_input }}
        INPUT_MODEL_CONTEXT_WINDOW: ${{ inputs.model_context_window }}
        INPUT_MODEL_MAX_TOKENS: ${{ inputs.model_max_tokens }}
        INPUT_COMPAT_SUPPORTS_DEVELOPER_ROLE: ${{ inputs.compat_supports_developer_role }}
        INPUT_COMPAT_SUPPORTS_REASONING_EFFORT: ${{ inputs.compat_supports_reasoning_effort }}
        INPUT_COMPAT_FORCE_ADAPTIVE_THINKING: ${{ inputs.compat_force_adaptive_thinking }}
        INPUT_EXTENSIONS: ${{ inputs.extensions }}
        INPUT_TRUST_PROJECT: ${{ inputs.trust_project }}
        INPUT_AGENT_DIR: ${{ inputs.agent_dir }}
        INPUT_PROMPT_TEMPLATE: ${{ inputs.prompt_template }}
        INPUT_OUTPUT_MODE: ${{ inputs.output_mode }}
        INPUT_PROMPT: ${{ inputs.prompt }}
        INPUT_PR_NUMBER: ${{ inputs.pr_number }}

    # Pushes the thread's refs/pi/threads/<number> if the step above was cancelled, timed out, or crashed
    # before its own final push. Fast-forward only: it never overwrites another run's history.
    - name: Save pi thread state
      if: always()
      shell: bash
      run: node --disable-warning=ExperimentalWarning ${{ github.action_path }}/src/push.ts
      env:
        INPUT_PR_NUMBER: ${{ inputs.pr_number }}
# Contributing to pi-action

This document covers development setup, architecture details, and contribution guidelines for pi-action.

## Development Setup

### Prerequisites

- Node.js 24+ (LTS)
- npm

### Getting Started

```bash
# Clone the repository
git clone https://github.com/cv/pi-action.git
cd pi-action

# Install dependencies (also sets up git hooks)
npm install

# Run tests
npm test

# Run tests with coverage
npm run coverage

# Build
npm run build

# Type check
npm run typecheck

# Run the complete quality gate
npm run check

# Run formatting and lint checks only
npm run lint

# Run dead-code and duplication analysis only
npm run analyze

# Apply safe lint/format fixes
npm run fix
```

## Git Hooks

This project uses [prek](https://github.com/j178/prek) to enforce quality checks via git hooks. Hooks are configured in [`.pre-commit-config.yaml`](.pre-commit-config.yaml) and are automatically installed when you run `npm install`.

| Hook | What it does |
|------|--------------|
| **pre-commit** | Runs fast tests and linting |
| **commit-msg** | Enforces [Conventional Commits](https://www.conventionalcommits.org/) format via commitlint |
| **prepare-commit-msg** | Auto-appends issue number from branch name via [`scripts/prepare-commit-msg.js`](scripts/prepare-commit-msg.js) (e.g., `feat/123-description` → `Refs #123`) |
| **pre-push** | Runs the test suite with coverage thresholds from [`vitest.config.ts`](vitest.config.ts) |

### Commit Message Format

Commits must follow the conventional commits format:

```
type(scope?): subject

body?

footer?
```

**Allowed types:** `feat`, `fix`, `docs`, `style`, `refactor`, `perf`, `test`, `build`, `ci`, `chore`, `revert`

**Examples:**
```bash
git commit -m "feat: add webhook support"
git commit -m "fix(agent): handle empty response from API"
git commit -m "docs: update installation instructions"
```

### Branch Naming

Use branch names like `feat/123-description` or `fix/456-bug-name` to automatically link commits to issues via the `prepare-commit-msg` hook.

## Architecture

The action is built with TypeScript on [pi-durable](https://www.npmjs.com/package/@earendil-works/pi-durable) and [pi-ai](https://www.npmjs.com/package/@earendil-works/pi-ai). Each issue/PR is a durable conversation whose storage is a chain of git commits on `refs/pi/threads/<number>` (the storage backend is in `src/storage/`).

### Source Files

| File | Description |
|------|-------------|
| [`src/index.ts`](src/index.ts) | Entry point - wires up dependencies and runs the action |
| [`src/run.ts`](src/run.ts) | Main orchestration logic |
| [`src/run-context.ts`](src/run-context.ts) | Resolving what to run on: a trigger, `pr_number`, or a direct prompt |
| [`src/thread.ts`](src/thread.ts) | One issue/PR as a durable pi conversation stored in git |
| [`src/conversation.ts`](src/conversation.ts) | Submitting triggers, waiting within the timeout, delivering each result once |
| [`src/triggers.ts`](src/triggers.ts) | Finding the `@pi` comments a thread still has to answer |
| [`src/models.ts`](src/models.ts) | Built-in providers with the `api_key` input as an in-memory credential |
| [`src/custom-provider.ts`](src/custom-provider.ts) | The single custom provider/model from the flat `provider_*`/`model_*` inputs |
| [`src/extensions.ts`](src/extensions.ts) | The `extensions` input: installing pi extensions from npm, finding their entry points, loading them with jiti, and the `pi` object they get |
| [`src/extension-provider.ts`](src/extension-provider.ts) | Turning an extension's `pi.registerProvider(name, config)` into a pi-ai provider |
| [`src/durable-extensions.ts`](src/durable-extensions.ts) | Creating the pi-durable extensions (`pi.durable`) with the run's host options |
| [`src/github-ui.ts`](src/github-ui.ts) | Questions from pi-durable extensions (`ui.ask`) as GitHub comments with checkboxes or a request for an `/answer` reply, posted without waiting; `ui.notify` in the job summary |
| [`src/answers.ts`](src/answers.ts) | Answers from the run's event (a box ticked on a question, an `/answer` reply), checked and turned into a `ui.answer` submission for the thread |
| [`src/push.ts`](src/push.ts) | The `if: always()` step that pushes unsaved thread state |
| [`src/storage/git.ts`](src/storage/git.ts) | In-process git objects and compare-and-swap ref updates |
| [`src/storage/git-storage.ts`](src/storage/git-storage.ts) | `GitStorage`: a pi-durable `Storage` whose log is a chain of commits on one ref |
| [`src/storage/sync.ts`](src/storage/sync.ts) | `GitSync`: fetching a thread ref and pushing it (fast-forward only) at turn boundaries |
| [`src/tool-env.ts`](src/tool-env.ts) | The variables the agent's tools get when the runner lacks them: `GH_TOKEN` and a `github-actions[bot]` git identity |
| [`src/github.ts`](src/github.ts) | GitHub API client helpers |
| [`src/inputs.ts`](src/inputs.ts) | Reading the action inputs (with their defaults) into `ActionInputs` |
| [`src/context.ts`](src/context.ts) | Prompt building and trigger extraction |
| [`src/security.ts`](src/security.ts) | Permission validation and input sanitization |
| [`src/formatting.ts`](src/formatting.ts) | Response formatting utilities |
| [`src/types.ts`](src/types.ts) | TypeScript type definitions |
| [`src/defaults.ts`](src/defaults.ts) | Centralized default values |
| [`src/utils.ts`](src/utils.ts) | General utility functions |
| [`src/test-helpers.ts`](src/test-helpers.ts) | Shared test utilities |

### Key Components

#### [`index.ts`](src/index.ts)
Entry point that reads GitHub Actions inputs, creates dependencies, and invokes `run()`. This is the only file with side effects (reading environment, calling APIs).

#### [`inputs.ts`](src/inputs.ts)
Reads every action input into `ActionInputs`, including the custom provider's `provider_*`/`model_*` inputs, falling back to [`defaults.ts`](src/defaults.ts) for empty or invalid values (CSV allowlists, booleans, positive integers). It takes the input reader as a parameter, so it is unit tested without loading the GitHub Actions runtime.

#### [`run.ts`](src/run.ts)
Main orchestration that:
1. Resolves the run context (trigger, `pr_number`, or direct prompt) and validates permissions
2. Sets up models from environment variables, the runtime-only `api_key` input, providers registered by pi extensions (`extensions`), and the custom provider inputs
3. Opens the thread (fetching `refs/pi/threads/<number>`; in memory for direct prompts)
4. Submits every unanswered `@pi` comment, then polls for new ones while pi works (comment mode), or runs one request (output mode, `pr_number`, direct prompts)
5. Posts each answer (or failure) once, or sets the action outputs
6. Pushes the thread

#### [`thread.ts`](src/thread.ts)
Wraps a pi-durable `Harness` on `GitStorage`:
- Fetches the thread ref, opens the conversation, resumes unfinished work
- Pushes the ref at every turn boundary (`GitSync`, fast-forward only)
- Submits comments with their GitHub ID as `requestId`, so each is answered once
- Records which results were posted, so a restarted run doesn't post them twice

#### [`github.ts`](src/github.ts)
Provides a clean interface to GitHub APIs:
- `extractTriggerInfo()`: Parses GitHub webhook payloads
- `GitHubClient`: Interface for reactions (on the issue, an issue comment, or a review comment), comments, PRs and their diffs

#### [`context.ts`](src/context.ts)
Handles prompt construction:
- `hasTrigger()`: Checks if text contains the trigger phrase
- `extractTask()`: Extracts the task from trigger text
- `buildPrompt()`: Constructs the full prompt with context
- `renderTemplate()`: Renders custom prompt templates

#### [`security.ts`](src/security.ts)
Permission and input validation:
- `validatePermissions()`: Checks the author against configured user, association, and bot allowlists
- `sanitizeInput()`: Removes HTML comments and invisible Unicode characters

### Action Configuration

The [`action.yml`](action.yml) file defines:
- Input parameters
- A composite action that:
  1. Sets up Node.js 24 if the job's Node is older
  2. Installs the runtime npm dependencies (`--omit=dev`)
  3. Installs standalone git hooks for conventional commits (see [`scripts/install-agent-hooks.js`](scripts/install-agent-hooks.js))
  4. Runs `src/index.ts` with Node's built-in TypeScript support, then `src/push.ts` in an `if: always()` step

### Testing

Tests use [Vitest](https://vitest.dev/) and are colocated with source files (`*.test.ts`).

**Running tests:**
```bash
npm test                    # Run once
npm run test:watch          # Watch mode
npm run coverage            # With coverage report
```

**Test philosophy:**
- All business logic has near-100% test coverage
- Tests use dependency injection for easy mocking
- Mock the pi SDK to test agent integration without real API calls
- Use [`test-helpers.ts`](src/test-helpers.ts) for common mock factories
- pi extensions used as fixtures live in [`test/fixtures/extensions/`](test/fixtures/extensions/); [`echo-provider`](test/fixtures/extensions/echo-provider/) registers a provider built on pi-ai's faux provider, so the `extensions` input can be tested end to end without network access; [`durable-ask`](test/fixtures/extensions/durable-ask/) is a pi-durable extension package with a tool that asks two questions the way pit does on an asynchronous host (`ui.ask`, then `ui.answer` entries on later runs)

**Coverage thresholds (enforced by pre-push hook):**
- Statements: 90%
- Lines: 90%
- Functions: 90%
- Branches: 85%

Thresholds and production coverage includes are configured in [`vitest.config.ts`](vitest.config.ts).

### Building

```bash
npm run build
```

This verifies the TypeScript production entrypoint without emitting JavaScript. Node runs the TypeScript directly (type stripping), so there is no build output and no `dist/`. That's why imports use `.ts` extensions and the code sticks to erasable syntax (no enums, namespaces, or parameter properties); `erasableSyntaxOnly` in `tsconfig.json` enforces it.

## CI/CD

### GitHub Actions Workflows

- [**CI (`ci.yml`)**](.github/workflows/ci.yml): Runs on push/PR to main - type checking, linting, and tests
- [**pi Assistant (`pi-assistant.yml`)**](.github/workflows/pi-assistant.yml): Dogfooding - uses the action from this repo to respond to `@pi` triggers

### Release Process

1. Ensure all tests pass and coverage thresholds are met
2. Update version in `package.json`
3. Create a new release/tag (e.g., `v1.0.1`)
4. Users reference the action via `cv/pi-action@v2`

## Code Style

- TypeScript with every strict compiler option on (see [`tsconfig.json`](tsconfig.json)); Node runs it directly, so only erasable syntax
- [oxlint](https://oxc.rs/docs/guide/usage/linter) with type-aware rules (see [`.oxlintrc.json`](.oxlintrc.json)): every rule category except the experimental `nursery` is an error, plus `typescript/no-unnecessary-condition` from it. Rules that are off are grouped with the reason they are off. Warnings fail the build, and so do `oxlint-disable` comments that no longer suppress anything
- [oxfmt](https://oxc.rs/docs/guide/usage/formatter) formats the code and JSON, and sorts imports (see [`.oxfmtrc.json`](.oxfmtrc.json)); Markdown and YAML are formatted by hand
- An `oxlint-disable-next-line <rule> -- <reason>` comment is fine when a rule is wrong for one line; put the reason after `--`
- Values from outside (JSON, GitHub payloads, git output) are `unknown` until checked, not cast

## Pull Request Guidelines

1. **Create a branch** with a descriptive name: `feat/123-description` or `fix/456-bug-name`
2. **Write tests** for any new functionality
3. **Ensure all hooks pass** - tests, type checking, linting, coverage
4. **Follow conventional commits** for your commit messages
5. **Keep changes focused** - one feature/fix per PR
6. **Update documentation** if adding new features or changing behavior

## Questions?

Open an issue or start a discussion on the repository.

ops:
// A pi-durable Storage that keeps its log as a chain of git commits on one ref.
//
// Like the JSONL backend, the state lives in a MemoryStorage; every stored batch is one git commit whose tree holds
// `batch.json` ({ format, seq, writes }), parented on the previous batch. Opening replays the chain from its root.
// The ref moves by compare-and-swap, so a second writer on the same ref fails instead of forking the log.
import type { Context } from "@earendil-works/chord/context";
import {
	type ConversationId,
	type EntryId,
	type Id,
	MemoryStorage,
	type Seq,
	type Storage,
	type StorageWrite,
} from "@earendil-works/pi-durable";

import { GitRepo, type Signature } from "./git.ts";

const FORMAT_VERSION = 1;
const BATCH_FILE = "batch.json";
const DEFAULT_AUTHOR: Signature = {
	name: "pi-durable",
	email: "pi-durable@localhost",
};

export interface GitStorageOptions {
	/** A work tree, `.git` dir, or bare repository. It must exist. */
	readonly repo: string;
	/** The ref holding the log, e.g. `refs/pi/threads/42`. */
	readonly ref: string;
	/** Commit author and committer. */
	readonly author?: Signature;
	/**
	 * Called after each stored commit() with the new tip and the batches it added, e.g. to push at turn boundaries
	 * (see `isTurnBoundary`). Must not throw; errors are swallowed.
	 */
	readonly onCommit?: (event: CommitEvent) => void;
}

interface CommitEvent {
	readonly tip: string;
	readonly batches: readonly Batch[];
}

export interface Batch {
	readonly format: number;
	readonly seq: number;
	readonly writes: readonly StorageWrite[];
}

class GitStorageCorruptionError extends Error {
	constructor(message: string, options?: { cause?: unknown }) {
		super(message, options);
		this.name = "GitStorageCorruptionError";
	}
}
export class GitStoragePoisonedError extends Error {
	constructor(cause: unknown) {
		super("Git storage is poisoned and must be reopened", { cause });
		this.name = "GitStoragePoisonedError";
	}
}

export class GitStorage implements Storage {
	readonly repo: GitRepo;
	readonly ref: string;
	private readonly author: Signature;
	private readonly onCommit: GitStorageOptions["onCommit"];
	private readonly memory = new MemoryStorage();
	private head: string | undefined;
	private closed = false;
	private poisonError: GitStoragePoisonedError | undefined;
	/** Settles once the batches being written are; memory is ahead of the ref meanwhile. */
	private writing: Promise<void> | undefined;
	/** Serializes commit() calls. */
	private queue: Promise<void> = Promise.resolve();

	private constructor(repo: GitRepo, options: GitStorageOptions) {
		this.repo = repo;
		this.ref = options.ref;
		this.author = options.author ?? DEFAULT_AUTHOR;
		this.onCommit = options.onCommit;
	}

	static async open(options: GitStorageOptions): Promise<GitStorage> {
		const repo = await GitRepo.open(options.repo);
		const storage = new GitStorage(repo, options);
		try {
			await storage.recover();
		} catch (error) {
			await repo.close();
			throw error;
		}
		return storage;
	}

	/** The commit the ref points at, as of the last commit or open; undefined while empty. */
	get tip(): string | undefined {
		return this.head;
	}

	private async recover(): Promise<void> {
		const tip = await this.repo.readRef(this.ref);
		this.head = tip;
		if (tip === undefined) {
			return;
		}
		const chain = await this.repo.commits(tip);
		const merge = chain.find((commit) => commit.parents.length > 1);
		if (merge) {
			throw new GitStorageCorruptionError(
				`Merge commit ${merge.id} in ${this.ref}`,
			);
		}
		// All reads go to one cat-file process, which pipelines them.
		const batches = await Promise.all(
			chain.map(async ({ id: sha }) => {
				const content = await this.repo
					.readFile(sha, BATCH_FILE)
					.catch((error: unknown) => {
						throw new GitStorageCorruptionError(
							`Commit ${sha} has no ${BATCH_FILE}`,
							{ cause: error },
						);
					});
				let batch: unknown;
				try {
					batch = JSON.parse(content.toString("utf8"));
				} catch (error) {
					throw new GitStorageCorruptionError(
						`Malformed ${BATCH_FILE} in ${sha}`,
						{ cause: error },
					);
				}
				if (!isBatch(batch)) {
					throw new GitStorageCorruptionError(
						`Unsupported or invalid batch in ${sha}`,
					);
				}
				return { sha, batch };
			}),
		);
		for (const { sha, batch } of batches) {
			try {
				// oxlint-disable-next-line typescript/no-unsafe-type-assertion -- Seq is a branded number; the log is where seqs come from
				this.memory.prepareCommit(batch.writes, batch.seq as Seq).apply();
			} catch (error) {
				throw new GitStorageCorruptionError(
					`Invalid committed state at seq ${batch.seq} (${sha})`,
					{ cause: error },
				);
			}
		}
	}

	async commit(
		batches: readonly (readonly StorageWrite[])[],
		receive: (index: number, seq: Seq) => void,
		context: Context,
	): ReturnType<Storage["commit"]> {
		this.assertUsable();
		const previous = this.queue;
		const turn = Promise.withResolvers<undefined>();
		this.queue = turn.promise;
		await previous;
		const writing = Promise.withResolvers<undefined>();
		this.writing = writing.promise;
		const seqs: Seq[] = [];
		const encoded: Batch[] = [];
		let refused: { error: unknown } | undefined;
		try {
			this.assertUsable();
			for (const writes of batches) {
				let prepared: ReturnType<MemoryStorage["prepareCommit"]>;
				try {
					prepared = this.memory.prepareCommit(writes);
				} catch (error) {
					refused = { error };
					break;
				}
				encoded.push({
					format: FORMAT_VERSION,
					seq: prepared.seq,
					writes: prepared.writes,
				});
				seqs.push(prepared.apply());
			}
			if (encoded.length > 0) {
				await this.persist(encoded, context);
			}
		} catch (error) {
			// Memory ran ahead of the ref: once a batch applied, any failure poisons the storage.
			if (seqs.length === 0) {
				throw error;
			}
			throw this.poison(error);
		} finally {
			this.writing = undefined;
			writing.resolve(undefined);
			turn.resolve(undefined);
		}
		for (const [index, seq] of seqs.entries()) {
			receive(index, seq);
		}
		if (
			encoded.length > 0 &&
			this.head !== undefined &&
			this.onCommit !== undefined
		) {
			try {
				this.onCommit({ tip: this.head, batches: encoded });
			} catch {
				// observers never fail a commit
			}
		}
		return refused === undefined
			? { stored: seqs.length }
			: { stored: seqs.length, refused: refused.error };
	}

	private async persist(
		batches: readonly Batch[],
		_context: Context,
	): Promise<void> {
		let parent = this.head;
		// Each commit is the parent of the next, so the writes are sequential.
		/* oxlint-disable eslint/no-await-in-loop */
		for (const batch of batches) {
			const blob = await this.repo.writeBlob(JSON.stringify(batch));
			const tree = await this.repo.writeTree({ [BATCH_FILE]: blob });
			parent = await this.repo.writeCommit({
				tree,
				parents: parent === undefined ? [] : [parent],
				author: this.author,
				message: commitMessage(batch),
			});
		}
		/* oxlint-enable eslint/no-await-in-loop */
		if (parent === undefined) {
			return;
		}
		await this.repo.updateRef(this.ref, parent, this.head);
		this.head = parent;
	}

	async mintId<I extends Id<string>>(): Promise<I> {
		return this.store.mintId<I>();
	}
	async conversation(
		...args: Parameters<Storage["conversation"]>
	): ReturnType<Storage["conversation"]> {
		return (await this.readable()).conversation(...args);
	}
	async scanConversations(
		...args: Parameters<Storage["scanConversations"]>
	): ReturnType<Storage["scanConversations"]> {
		return (await this.readable()).scanConversations(...args);
	}
	entry(id: EntryId, context: Context): ReturnType<MemoryStorage["entry"]>;
	entry(
		conversationId: ConversationId,
		id: EntryId,
		context: Context,
	): ReturnType<MemoryStorage["entry"]>;
	async entry(
		idOrConversation: EntryId | ConversationId,
		idOrContext: EntryId | Context,
		context?: Context,
	): ReturnType<MemoryStorage["entry"]> {
		const memory = await this.readable();
		/* oxlint-disable typescript/no-unsafe-type-assertion -- the overloads differ by arity, so the third argument tells which one the caller used */
		return context === undefined
			? memory.entry(idOrConversation as EntryId, idOrContext as Context)
			: memory.entry(
					idOrConversation as ConversationId,
					idOrContext as EntryId,
					context,
				);
		/* oxlint-enable typescript/no-unsafe-type-assertion */
	}
	async findLatestHeadMarker(
		...args: Parameters<Storage["findLatestHeadMarker"]>
	): ReturnType<Storage["findLatestHeadMarker"]> {
		return (await this.readable()).findLatestHeadMarker(...args);
	}
	async scanEntries(
		...args: Parameters<Storage["scanEntries"]>
	): ReturnType<Storage["scanEntries"]> {
		return (await this.readable()).scanEntries(...args);
	}
	async task(
		...args: Parameters<Storage["task"]>
	): ReturnType<Storage["task"]> {
		return (await this.readable()).task(...args);
	}
	async scanTasks(
		...args: Parameters<Storage["scanTasks"]>
	): ReturnType<Storage["scanTasks"]> {
		return (await this.readable()).scanTasks(...args);
	}
	async submission(
		...args: Parameters<Storage["submission"]>
	): ReturnType<Storage["submission"]> {
		return (await this.readable()).submission(...args);
	}
	async scanSubmissions(
		...args: Parameters<Storage["scanSubmissions"]>
	): ReturnType<Storage["scanSubmissions"]> {
		return (await this.readable()).scanSubmissions(...args);
	}
	async submissionByRequest(
		...args: Parameters<Storage["submissionByRequest"]>
	): ReturnType<Storage["submissionByRequest"]> {
		return (await this.readable()).submissionByRequest(...args);
	}
	async findDocument(
		...args: Parameters<Storage["findDocument"]>
	): ReturnType<Storage["findDocument"]> {
		return (await this.readable()).findDocument(...args);
	}
	async document(
		...args: Parameters<Storage["document"]>
	): ReturnType<Storage["document"]> {
		return (await this.readable()).document(...args);
	}
	async scanDocuments(
		...args: Parameters<Storage["scanDocuments"]>
	): ReturnType<Storage["scanDocuments"]> {
		return (await this.readable()).scanDocuments(...args);
	}

	async close(context: Context): Promise<void> {
		if (this.closed) {
			return;
		}
		this.closed = true;
		await this.queue;
		await this.memory.close(context);
		await this.repo.close();
	}

	private get store(): MemoryStorage {
		this.assertUsable();
		return this.memory;
	}
	private async readable(): Promise<MemoryStorage> {
		while (this.writing !== undefined) {
			// oxlint-disable-next-line eslint/no-await-in-loop -- a new write may start while we wait
			await this.writing;
		}
		return this.store;
	}
	private poison(cause: unknown): GitStoragePoisonedError {
		this.poisonError ??= new GitStoragePoisonedError(cause);
		return this.poisonError;
	}
	private assertUsable(): void {
		if (this.closed) {
			throw new Error("GitStorage is closed");
		}
		if (this.poisonError !== undefined) {
			throw this.poisonError;
		}
	}
}

function isBatch(value: unknown): value is Batch {
	if (typeof value !== "object" || value === null) {
		return false;
	}
	return (
		Reflect.get(value, "format") === FORMAT_VERSION &&
		Number.isSafeInteger(Reflect.get(value, "seq")) &&
		Array.isArray(Reflect.get(value, "writes"))
	);
}

/** `pi-durable: seq 12 (entry, task×2)` plus trailers, so `git log` reads well. */
function commitMessage(batch: Batch): string {
	const counts = new Map<string, number>();
	for (const write of batch.writes) {
		counts.set(write.type, (counts.get(write.type) ?? 0) + 1);
	}
	const summary = [...counts]
		.map(([type, n]) => (n === 1 ? type : `${type}×${n}`))
		.join(", ");
	return `pi-durable: seq ${batch.seq} (${summary})\n\nPi-Durable-Format: ${batch.format}\nPi-Durable-Seq: ${batch.seq}\n`;
}
import { setTimeout as sleep } from "node:timers/promises";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import type { Submission } from "@earendil-works/pi-durable";

import { ANSWER_KIND } from "./answers.ts";
import type { Thread } from "./thread.ts";
import type { Trigger } from "./triggers.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type SettledRecord = Awaited<ReturnType<Submission["wait"]>>;

export type ThreadResult =
	| { success: true; response: string }
	| { success: false; error: string };

export interface ConversationOptions {
	thread: Thread;
	log: Log;
	timeoutSeconds: number;
	pollIntervalMs: number;
	/** The message to submit for a trigger; `first` is true for the first one of a new thread. */
	message: (trigger: Trigger, first: boolean) => Promise<string>;
	/**
	 * Deliver a result. `alreadyPosted` is set when an earlier run delivered this answer (the trigger was
	 * answered together with another one). Returns where it was posted, recorded so it is never posted twice.
	 */
	deliver: (
		trigger: Trigger,
		result: ThreadResult,
		alreadyPosted: boolean,
	) => Promise<string | undefined>;
	/** Triggers that arrived since the run started; omitted for one-off runs. */
	poll?: () => Promise<Trigger[]>;
	/** The URLs of the questions pi-durable extensions asked in this run so far (see github-ui.ts). */
	asked?: () => readonly string[];
}

const EMPTY_RESPONSE = "Agent returned empty response";
const SUMMARY_SUFFIX = "-summary";
const SUMMARY_PROMPT = `IMPORTANT: You completed your work but did not provide a final text summary. This summary is REQUIRED. Please now write a plain-text summary of what you accomplished, including:
- What changes were made and why
- Which files were modified
- Any errors encountered or remaining issues
- Confirmation that your work is complete

Do NOT call any tools - just provide the text summary.`;

function describeUnanswered(
	record: SettledRecord,
	timedOutAfter: number | undefined,
): string {
	if (record.reason === "aborted" && timedOutAfter !== undefined) {
		return `Timeout after ${timedOutAfter} seconds`;
	}
	if (record.detail === undefined) {
		return record.reason ?? "unanswered";
	}
	const detail =
		typeof record.detail === "string"
			? record.detail
			: JSON.stringify(record.detail);
	return `${record.reason}: ${detail}`;
}

/**
 * Drives a thread through a set of triggers: submits them (new ones join the running conversation), waits for
 * every answer within the timeout, and delivers each answer or failure exactly once.
 */
export class ThreadConversation {
	private readonly handled = new Set<string>();
	private readonly pending = new Set<Promise<void>>();
	private delivering: Promise<void> = Promise.resolve();
	private posted = new Map<string, string>();
	private timedOut = false;
	private readonly options: ConversationOptions;

	constructor(options: ConversationOptions) {
		this.options = options;
	}

	async run(initial: Trigger[]): Promise<void> {
		const { thread, log, timeoutSeconds, pollIntervalMs, poll } = this.options;
		this.posted = await thread.postedResults();
		await this.submitAll(initial);

		const deadline = Date.now() + timeoutSeconds * 1000;
		for (;;) {
			const remaining = deadline - Date.now();
			if (remaining <= 0) {
				this.timedOut = true;
				break;
			}
			if (this.pending.size > 0) {
				const wait = new AbortController();
				const timer = sleep(Math.min(pollIntervalMs, remaining), undefined, {
					signal: wait.signal,
				}).catch(() => undefined);
				// oxlint-disable-next-line eslint/no-await-in-loop -- the poll loop waits between rounds by design
				await Promise.race([Promise.allSettled(this.pending), timer]);
				wait.abort();
			}
			const fresh = poll
				? // oxlint-disable-next-line eslint/no-await-in-loop -- each round polls once, after the wait
					(await poll()).filter((trigger) => !this.handled.has(trigger.key))
				: [];
			if (fresh.length > 0) {
				log.info(
					`${fresh.length} new comment(s) for pi; adding them to the conversation`,
				);
				// oxlint-disable-next-line eslint/no-await-in-loop -- new comments join before the next round
				await this.submitAll(fresh);
			} else if (this.pending.size === 0) {
				break;
			}
		}

		if (this.timedOut) {
			log.warning(`Timeout after ${timeoutSeconds} seconds; aborting the run`);
			await thread.abort();
		}
		await Promise.allSettled(this.pending);
		await this.delivering;
	}

	private async submitAll(triggers: Trigger[]): Promise<void> {
		for (const trigger of triggers) {
			if (!this.handled.has(trigger.key)) {
				const first = this.options.thread.isNew && this.handled.size === 0;
				this.handled.add(trigger.key);
				// oxlint-disable-next-line eslint/no-await-in-loop -- triggers are submitted in order
				const content = await this.options.message(trigger, first);
				this.track(trigger, this.answer(trigger, content));
			}
		}
	}

	private track(trigger: Trigger, result: Promise<SettledResult>): void {
		const settled = (async () => {
			try {
				this.enqueueDelivery(trigger, await result);
			} catch (error) {
				this.options.log.warning(getErrorMessage(error));
			}
		})();
		this.pending.add(settled);
		settled
			.finally(() => {
				this.pending.delete(settled);
			})
			.catch(() => undefined);
	}

	/** Submit and wait; an empty answer is followed by one request for a summary (as pi-action always did). */
	private async answer(
		trigger: Trigger,
		content: string,
	): Promise<SettledResult> {
		const outcome = await this.submitAndWait(trigger, trigger.key, content);
		// An answer an earlier run delivered (or a question it is waiting on) is not asked for again.
		if (!(outcome.empty && !this.timedOut) || this.posted.has(outcome.key)) {
			return outcome;
		}
		this.options.log.warning(
			"Agent returned empty response from first attempt. Re-prompting for a summary.",
		);
		const retry = await this.submitAndWait(
			trigger,
			`${trigger.key}${SUMMARY_SUFFIX}`,
			SUMMARY_PROMPT,
		);
		if (!retry.empty) {
			return retry;
		}
		return {
			key: retry.key,
			empty: true,
			result: {
				success: false,
				error: `Agent failed to provide a response after two attempts. First attempt: ${EMPTY_RESPONSE}. Retry attempt: ${EMPTY_RESPONSE}.`,
			},
		};
	}

	private async submitAndWait(
		trigger: Trigger,
		key: string,
		content: string,
	): Promise<SettledResult> {
		const asked = this.options.asked ?? (() => []);
		const askedBefore = asked().length;
		const { answer } = trigger;
		const submission = await this.options.thread.submit({
			key,
			content,
			data: {
				author: trigger.author.login,
				source: trigger.source,
				...(trigger.url ? { url: trigger.url } : {}),
			},
			...(answer
				? {
						entry: {
							kind: ANSWER_KIND,
							data: {
								key: answer.key,
								kind: answer.kind,
								answer: answer.answer,
								by: answer.by,
								url: answer.url,
							},
						},
					}
				: {}),
		});
		const record = await submission.wait(BACKGROUND_CONTEXT);
		if (record.status === "done" && record.answer !== undefined) {
			const { text, toolCalls } = await this.options.thread.answerText(
				record.answer,
			);
			const questions = asked().slice(askedBefore);
			if (toolCalls && questions.length > 0) {
				// The run ended on a question (its tool round asked to terminate): the answer comes in a later run.
				return {
					key: `answer-${record.answer}`,
					empty: false,
					waiting: questions,
					result: { success: true, response: text },
				};
			}
			return {
				key: `answer-${record.answer}`,
				empty: text === "",
				result: text
					? { success: true, response: text }
					: { success: false, error: EMPTY_RESPONSE },
			};
		}
		const timedOutAfter = this.timedOut
			? this.options.timeoutSeconds
			: undefined;
		return {
			key: `error-${record.id}`,
			empty: false,
			result: {
				success: false,
				error: describeUnanswered(record, timedOutAfter),
			},
		};
	}

	private enqueueDelivery(trigger: Trigger, outcome: SettledResult): void {
		this.delivering = this.delivering
			.then(async () => this.deliver(trigger, outcome))
			.catch((error: unknown) => {
				this.options.log.warning(
					`Failed to deliver result: ${getErrorMessage(error)}`,
				);
			});
	}

	private async deliver(
		trigger: Trigger,
		outcome: SettledResult,
	): Promise<void> {
		const alreadyPosted = this.posted.has(outcome.key);
		if (outcome.waiting) {
			this.options.log.info(
				`pi asked a question and ended its turn; waiting for an answer to ${outcome.waiting.join(", ")}`,
			);
			if (!alreadyPosted) {
				this.posted.set(outcome.key, outcome.waiting[0] ?? "");
				await this.options.thread.markPosted(
					outcome.key,
					outcome.waiting[0] ?? "",
				);
			}
			return;
		}
		if (alreadyPosted && !outcome.result.success) {
			return; // a failure an earlier run already reported
		}
		const url = await this.options.deliver(
			trigger,
			outcome.result,
			alreadyPosted,
		);
		if (url !== undefined && !alreadyPosted) {
			this.posted.set(outcome.key, url);
			await this.options.thread.markPosted(outcome.key, url);
		}
	}
}

interface SettledResult {
	/** `answer-<entryId>` or `error-<submissionId>`: what is delivered once. */
	key: string;
	empty: boolean;
	result: ThreadResult;
	/** The run ended on these questions: nothing is posted, the answers start a later run. */
	waiting?: readonly string[];
}
name: 'pi-action'
description: 'Run a durable pi coding agent on GitHub issues and PRs: one conversation per thread, stored in git'
author: 'Carlos Villela'
branding:
  icon: 'cpu'
  color: 'purple'

inputs:
  github_token:
    description: 'GitHub token for API access (issues, PRs, reactions, comments)'
    required: true
  api_key:
    description: 'LLM provider API key (runtime-only; alternatively set provider-specific env vars like ANTHROPIC_API_KEY)'
    required: false
  trigger_phrase:
    description: 'Phrase to trigger pi (e.g., @pi)'
    default: '@pi'
  allowed_bots:
    description: 'Comma-separated list of allowed bot usernames'
    default: ''
  allowed_users:
    description: 'Comma-separated GitHub usernames allowed to trigger pi. If set, users must be in this list.'
    default: ''
  allowed_associations:
    description: 'Comma-separated GitHub author associations allowed to trigger pi when allowed_users is empty'
    default: 'OWNER,MEMBER'
  timeout:
    description: 'Seconds before the run is aborted (its thread is still saved)'
    default: '1800'
  poll_interval:
    description: 'Seconds between checks for new comments while pi works; new trigger comments join the running conversation'
    default: '15'
  provider:
    description: 'LLM provider (anthropic, openai, google, etc.)'
    default: 'anthropic'
  model:
    description: 'Model ID'
    default: 'claude-sonnet-5-5'
  provider_base_url:
    description: 'Base URL for a single custom provider/model (e.g., https://inference-api.nvidia.com)'
    required: false
  provider_api:
    description: 'API type for the custom provider/model'
    required: false
    default: 'openai-completions'
  provider_api_key:
    description: 'Provider apiKey config value for custom providers; can be a literal key or env var name'
    required: false
  provider_auth_header:
    description: 'Add Authorization: Bearer <key> for custom provider requests'
    required: false
    default: 'false'
  model_name:
    description: 'Display name for the custom model'
    required: false
  model_reasoning:
    description: 'Whether the custom model supports reasoning/thinking'
    required: false
    default: 'false'
  model_input:
    description: 'Comma-separated custom model input modalities (text or text,image)'
    required: false
    default: 'text'
  model_context_window:
    description: 'Context window tokens for the custom model'
    required: false
    default: '128000'
  model_max_tokens:
    description: 'Max output tokens for the custom model'
    required: false
    default: '16384'
  compat_supports_developer_role:
    description: 'Whether the OpenAI-compatible custom provider supports developer role messages'
    required: false
  compat_supports_reasoning_effort:
    description: 'Whether the OpenAI-compatible custom provider supports reasoning_effort'
    required: false
  compat_force_adaptive_thinking:
    description: 'Use adaptive thinking for an Anthropic-compatible custom model (required by Claude Opus 4.6+ and Sonnet 4.6+)'
    required: false
  extensions:
    description: 'pi extensions to load: npm package specs or paths relative to the workspace, one per line or comma-separated. pi extensions contribute the model providers they register; packages with a pi-durable extension (pi.durable in package.json) add their tools to the conversation. npm packages are installed into a temp directory without lifecycle scripts. Extensions run inside the action with the job''s permissions and environment.'
    required: false
    default: ''
  trust_project:
    description: 'Let pi-durable extensions trust the repository: load and run its own configuration (such as .pi/ files). Only for repositories whose code you would run anyway; anyone who can open a PR can change those files.'
    required: false
    default: 'false'
  agent_dir:
    description: 'Agent directory (user-level state) for pi-durable extensions, relative to the workspace; a fresh temp directory under RUNNER_TEMP when empty'
    required: false
    default: ''
  prompt_template:
    description: 'Custom prompt template with placeholder variables'
    required: false
  output_mode:
