import type { Models } from "@earendil-works/pi-ai/models";
import type { Extension } from "@earendil-works/pi-durable";

import { buildPrompt, formatFollowUp, type PIContext } from "./context.ts";
import { ThreadConversation, type ThreadResult } from "./conversation.ts";
import { createDurableExtensions } from "./durable-extensions.ts";
import { loadExtensions } from "./extensions.ts";
import { formatErrorComment, formatSuccessComment } from "./formatting.ts";
import { createGitHubUi, type GitHubUi } from "./github-ui.ts";
import type { GitHubClient, ReactionTarget } from "./github.ts";
import type { ActionInputs } from "./inputs.ts";
import { createActionModels, findModel } from "./models.ts";
import { getRunContext } from "./run-context.ts";
import { GitSyncConflictError } from "./storage/sync.ts";
import { Thread } from "./thread.ts";
import { toolEnv } from "./tool-env.ts";
import { collectTriggers, type Trigger, triggerFromInfo } from "./triggers.ts";
import type { Log, TriggerInfo } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type Env = Record<string, string | undefined>;

export interface Logger extends Log {
	error: (msg: string) => void;
	setFailed: (msg: string) => void;
	setOutput: (name: string, value: string) => void;
}

export interface ActionDependencies {
	inputs: ActionInputs;
	/** The webhook payload of the event that started the workflow. */
	payload: Record<string, unknown>;
	createClient: (token: string) => GitHubClient;
	log: Logger;
	cwd: string;
	/** Override model setup (tests use a faux provider). */
	createModels?: ((inputs: ActionInputs) => Promise<Models>) | undefined;
	/** Git remote holding the thread refs. Default "origin". */
	remote?: string;
	env?: Env;
	/** Appends Markdown to the job summary (notifications from pi-durable extensions). */
	summary?: (markdown: string) => Promise<void>;
}

/**
 * The `extensions` input and the model setup: the built-in and custom providers and those extensions register
 * (unless `createModels` overrides it), the pi-durable extensions for the thread, which get the GitHub UI when
 * the run posts to an issue or PR, and the variables the agent's tools get (see `toolEnv()`). pi-durable extensions
 * run in this process, so when there are any, those variables are set in its environment too (after npm ran).
 */
async function setUp(
	deps: ActionDependencies,
	gh: GitHubClient,
	issueNumber: number | undefined,
): Promise<{
	models: Models;
	extensions: Extension[];
	tools: Record<string, string>;
	ui: GitHubUi | undefined;
}> {
	const { inputs, log, cwd } = deps;
	const env = deps.env ?? process.env;
	const loaded = await loadExtensions({
		specs: inputs.extensions,
		cwd,
		log,
		env,
	});
	const models = deps.createModels
		? await deps.createModels(inputs)
		: await createActionModels(inputs, {
				providers: loaded.providers,
				env,
				log,
			});
	const tools = await toolEnv({ token: inputs.githubToken, cwd, env });
	if (Object.keys(tools).length > 0) {
		log.info(`The agent's tools get ${Object.keys(tools).join(", ")}`);
	}
	if (loaded.durable.length > 0) {
		Object.assign(env, tools);
	}
	const ui =
		inputs.outputMode === "comment" && issueNumber !== undefined
			? createGitHubUi({ gh, issueNumber, log, summary: deps.summary })
			: undefined;
	const extensions = await createDurableExtensions(loaded.durable, {
		cwd,
		agentDir: inputs.agentDir,
		trustProject: inputs.trustProject,
		ui,
		log,
		env,
	});
	return { models, extensions, tools, ui };
}

/** On cancellation (SIGINT, then SIGTERM), push what the thread has so far before the runner kills us. */
function pushOnSignals(thread: Thread, log: Log): () => void {
	const handler = (signal: NodeJS.Signals) => {
		log.warning(`Received ${signal}; saving the thread before exiting`);
		thread
			.push()
			.catch((error: unknown) => {
				log.warning(getErrorMessage(error));
			})
			.finally(() => {
				process.exitCode = 1;
				process.kill(process.pid, "SIGKILL");
			})
			.catch(() => undefined);
	};
	process.once("SIGINT", handler);
	process.once("SIGTERM", handler);
	return () => {
		process.off("SIGINT", handler);
		process.off("SIGTERM", handler);
	};
}

/** The context of the first message of a thread, for the trigger that starts it. */
function contextFor(piContext: PIContext, trigger: Trigger): PIContext {
	return piContext.type === "direct"
		? piContext
		: { ...piContext, task: trigger.task, triggerComment: trigger.text };
}

/** A run from workflow_dispatch or a direct prompt: one request, keyed by the workflow run. */
function oneOffTrigger(piContext: PIContext, env: Env): Trigger {
	const runId = env["GITHUB_RUN_ID"] ?? String(Date.now());
	const attempt = env["GITHUB_RUN_ATTEMPT"] ?? "1";
	return {
		key: `run-${runId}-${attempt}`,
		source: "body",
		issueNumber: piContext.type === "direct" ? 0 : piContext.number,
		author: { login: env["GITHUB_ACTOR"] ?? "workflow", type: "User" },
		text: piContext.task,
		task: piContext.task,
		createdAt: new Date().toISOString(),
	};
}

/** What the run starts with: every unanswered trigger on the thread in comment mode, else one request. */
async function initialTriggers(
	deps: ActionDependencies,
	gh: GitHubClient,
	piContext: PIContext,
	triggerInfo: TriggerInfo | undefined,
	since: Date | undefined,
	answer: Trigger | undefined,
): Promise<Trigger[]> {
	const { inputs } = deps;
	if (!triggerInfo) {
		return [oneOffTrigger(piContext, deps.env ?? process.env)];
	}
	const current = answer ?? triggerFromInfo(triggerInfo, inputs.triggerPhrase);
	return inputs.outputMode === "comment"
		? collectTriggers(gh, triggerInfo, inputs, since, current)
		: [current];
}

/** Close the thread, pushing it; a failure to save is a warning, not a failed run. */
async function closeThread(thread: Thread, log: Log): Promise<void> {
	try {
		await thread.close();
	} catch (error) {
		log.warning(
			error instanceof GitSyncConflictError
				? `${thread.ref} moved on the remote while this run worked; its history was not pushed. ${getErrorMessage(error)}`
				: `Could not save the thread: ${getErrorMessage(error)}`,
		);
	}
}

export async function run(deps: ActionDependencies): Promise<void> {
	const resolved = await getRunContext(deps);
	if (!resolved) {
		return;
	}
	const { piContext, ghClient: gh, triggerInfo } = resolved;
	const { inputs, log } = deps;
	log.info(`Running pi agent for: ${piContext.task}`);
	const issueNumber =
		piContext.type === "direct" ? undefined : piContext.number;
	// In comment mode, a trigger makes the run a conversation on its issue or PR (reactions, new comments join).
	const interactive = inputs.outputMode === "comment" ? triggerInfo : undefined;

	/** Set the outputs, or react on `target` and post the result unless it was posted before. Returns where it went. */
	const report = async (
		result: ThreadResult,
		target: ReactionTarget | undefined,
		ref?: string,
		alreadyPosted = false,
	): Promise<string | undefined> => {
		if (!result.success) {
			log.error(`pi execution failed: ${result.error}`);
		}
		if (inputs.outputMode === "output") {
			log.setOutput("success", String(result.success));
			log.setOutput(
				"response",
				result.success ? result.response : result.error,
			);
			return "output";
		}
		if (target) {
			await gh.addReaction(target, result.success ? "rocket" : "confused");
		}
		if (alreadyPosted || issueNumber === undefined) {
			return undefined;
		}
		const body = result.success
			? formatSuccessComment(result.response, ref)
			: formatErrorComment(result.error, ref);
		return (await gh.createComment(issueNumber, body)).url;
	};

	if (interactive) {
		await gh.addReaction(interactive, "eyes");
	}
	let thread: Thread | undefined;
	let stopSignals: (() => void) | undefined;
	try {
		const { models, extensions, tools, ui } = await setUp(
			deps,
			gh,
			issueNumber,
		);
		const opened = await Thread.open({
			cwd: deps.cwd,
			issueNumber,
			models,
			model: findModel(models, inputs.provider, inputs.model),
			log,
			remote: deps.remote,
			extensions,
			toolEnv: tools,
		});
		thread = opened;
		stopSignals = pushOnSignals(opened, log);
		log.info(
			opened.ref
				? `Thread ${opened.ref}: ${opened.isNew ? "new" : `since ${opened.startedAt?.toISOString()}`}`
				: "One-off conversation (not stored)",
		);
		// New comments: on a new thread, from the time of the trigger; on an existing one, since it began.
		const since =
			opened.startedAt ??
			new Date(
				Date.parse(interactive?.createdAt ?? new Date().toISOString()) - 1000,
			);
		const conversation = new ThreadConversation({
			thread: opened,
			log,
			timeoutSeconds: inputs.timeout,
			pollIntervalMs: inputs.pollInterval * 1000,
			message: async (trigger, first) => {
				if (trigger.answer) {
					return trigger.text;
				}
				return first
					? buildPrompt(contextFor(piContext, trigger), inputs.promptTemplate)
					: formatFollowUp(trigger);
			},
			deliver: async (trigger, result, alreadyPosted) =>
				report(
					result,
					interactive ? trigger : undefined,
					opened.ref,
					alreadyPosted,
				),
			...(interactive
				? { poll: async () => collectTriggers(gh, interactive, inputs, since) }
				: {}),
			...(ui ? { asked: () => ui.asked } : {}),
		});
		await conversation.run(
			await initialTriggers(
				deps,
				gh,
				piContext,
				triggerInfo,
				opened.startedAt,
				resolved.answer,
			),
		);
	} catch (error) {
		await report(
			{ success: false, error: getErrorMessage(error) },
			interactive,
		);
	} finally {
		stopSignals?.();
		if (thread) {
			await closeThread(thread, log);
		}
	}
}
// Answers to questions from pi-durable extensions, from the webhook event of a new run: a box ticked on a question
// (`issue_comment` `edited`) or an `/answer` reply (`issue_comment` `created`). Each becomes one submission to the
// thread: a message for the model, placed as a `ui.answer` entry that pit returns when the program asks again.
import {
	answeredBody,
	oneLine,
	parseQuestion,
	type PostedQuestion,
	readAnswerReply,
} from "./github-ui.ts";
import { extractTriggerInfo, type GitHubClient, toUserType } from "./github.ts";
import { type Allowlists, validatePermissions } from "./security.ts";
import type { Trigger } from "./triggers.ts";
import type {
	GitHubComment,
	GitHubUser,
	Log,
	TriggerInfo,
	UiAnswer,
} from "./types.ts";
import { getErrorMessage } from "./utils.ts";

export const ANSWER_KIND = "ui.answer";
/** Roles that can edit pi-action's comments (and so tick its boxes). */
const WRITE_ROLES = new Set(["admin", "maintain", "write"]);

/** An answer, and the issue or PR it belongs to. */
export interface AnswerEvent {
	info: TriggerInfo;
	trigger: Trigger;
}

export interface AnswerOptions {
	gh: GitHubClient;
	allow: Allowlists;
	log: Log;
}

function field(value: unknown, ...path: string[]): unknown {
	let current = value;
	for (const key of path) {
		current =
			typeof current === "object" && current !== null
				? Reflect.get(current, key)
				: undefined;
	}
	return current;
}

const text = (value: unknown): string =>
	typeof value === "string" ? value : "";

/** What the event is for questions: a question comment that was edited, an `/answer` reply, or neither. */
export function questionEventKind(
	payload: Record<string, unknown>,
): "edit" | "reply" | undefined {
	if (field(payload, "issue") === undefined) {
		return undefined;
	}
	const body = text(field(payload, "comment", "body"));
	const action = field(payload, "action");
	if (action === "edited") {
		return parseQuestion(body) ? "edit" : undefined;
	}
	return action === "created" && readAnswerReply(body) ? "reply" : undefined;
}

/** The value pit gets, and how the answer is shown. */
function valueOf(
	question: PostedQuestion,
	index: number,
): { answer: boolean | string; shown: string } {
	const label = question.options[index] ?? "";
	return question.kind === "confirm"
		? { answer: index === 0, shown: label }
		: { answer: label, shown: label };
}

function answerTrigger(
	info: TriggerInfo,
	answer: UiAnswer,
	shown: string,
	from: {
		author: GitHubUser;
		commentId: number;
		questionId: number;
		createdAt: string;
	},
): AnswerEvent {
	const message = `**@${answer.by}** answered pi's question *${oneLine(answer.title)}* (${answer.url}): ${shown}`;
	return {
		info,
		trigger: {
			// One per question comment: a question asked again later (same key) is a new comment, and a new answer.
			key: `answer-${answer.key}-${from.questionId}`,
			source: "comment",
			issueNumber: info.issueNumber,
			commentId: from.commentId,
			author: from.author,
			text: message,
			task: message,
			createdAt: from.createdAt,
			url: answer.url,
			answer,
		},
	};
}

/** Whether `sender`, who edited pi-action's comment, may answer: write access, and the action's allowlists. */
async function mayTick(
	sender: GitHubUser,
	options: AnswerOptions,
): Promise<boolean> {
	if (sender.type === "Bot") {
		return validatePermissions(sender, "", options.allow);
	}
	if (
		options.allow.allowedUsers.length > 0 &&
		!validatePermissions(sender, "", options.allow)
	) {
		return false;
	}
	const role = await options.gh
		.getCollaboratorPermission(sender.login)
		.catch((error: unknown) => {
			options.log.warning(
				`Could not check @${sender.login}'s permission: ${getErrorMessage(error)}`,
			);
			return "none";
		});
	return WRITE_ROLES.has(role);
}

async function settle(
	gh: GitHubClient,
	comment: { id: number; body: string },
	shown: string,
	login: string,
	log: Log,
): Promise<void> {
	try {
		await gh.updateComment(
			comment.id,
			answeredBody(comment.body, shown, login),
		);
	} catch (error) {
		log.warning(
			`Could not mark the question answered: ${getErrorMessage(error)}`,
		);
	}
}

/** A box ticked on a question: the first box that was unticked before the edit and is ticked now. */
async function fromEdit(
	payload: Record<string, unknown>,
	info: TriggerInfo,
	options: AnswerOptions,
): Promise<AnswerEvent | undefined> {
	const { gh, log } = options;
	const commentId = Number(field(payload, "comment", "id"));
	const after = parseQuestion(text(field(payload, "comment", "body")));
	const before = parseQuestion(text(field(payload, "changes", "body", "from")));
	if (!(after && before) || before.key !== after.key || before.answered) {
		log.info("An edit of a question that is not a new answer; skipping");
		return undefined;
	}
	const sameOptions =
		before.options.length === after.options.length &&
		before.options.every((option, i) => option === after.options[i]);
	const index = after.ticked.findIndex(
		(ticked, i) => ticked && before.ticked[i] === false,
	);
	if (!sameOptions || index === -1) {
		log.info("No box was newly ticked on the question; skipping");
		return undefined;
	}
	const current = await gh.getComment(commentId);
	const now = parseQuestion(current.body ?? "");
	if (now?.key !== after.key || now.answered) {
		log.info(`The question ${info.url ?? ""} is already answered; skipping`);
		return undefined;
	}
	const login = text(field(payload, "sender", "login"));
	const sender: GitHubUser = {
		login,
		type: toUserType(text(field(payload, "sender", "type"))),
	};
	if (!(login && (await mayTick(sender, options)))) {
		log.warning(
			`@${login} ticked a box on ${info.url ?? "a question"} but may not answer (it takes write access and the allowed_* inputs); ignoring it`,
		);
		return undefined;
	}
	const { answer, shown } = valueOf(after, index);
	const url = info.url ?? current.html_url;
	log.info(`@${login} answered ${oneLine(after.title)} (${url}): ${shown}`);
	await settle(
		gh,
		{ id: commentId, body: current.body ?? "" },
		shown,
		login,
		log,
	);
	return answerTrigger(
		{ ...info, author: sender },
		{
			key: after.key,
			kind: after.kind,
			answer,
			by: login,
			url,
			title: after.title,
		},
		shown,
		{
			author: sender,
			commentId,
			questionId: commentId,
			createdAt:
				text(field(payload, "comment", "updated_at")) ||
				new Date().toISOString(),
		},
	);
}

/** The open `input` question a reply answers: the one it quotes, else the oldest one posted before it. */
function questionFor(
	comments: readonly GitHubComment[],
	replyId: number,
	quote: string,
): { comment: GitHubComment; question: PostedQuestion } | undefined {
	const open = comments.flatMap((comment) => {
		const question = parseQuestion(comment.body ?? "");
		return question?.kind === "input" &&
			!question.answered &&
			comment.id < replyId
			? [{ comment, question }]
			: [];
	});
	return (
		open.find(
			({ question }) => quote !== "" && quote.includes(question.title),
		) ?? open[0]
	);
}

/** 👍 on the reply that answered a question. */
async function thumbsUp(
	gh: GitHubClient,
	issueNumber: number,
	commentId: number,
	log: Log,
): Promise<void> {
	try {
		await gh.addReaction({ source: "comment", issueNumber, commentId }, "+1");
	} catch (error) {
		log.warning(`Could not react to the answer: ${getErrorMessage(error)}`);
	}
}

/** An `/answer` reply from someone allowed to run pi. */
async function fromReply(
	info: TriggerInfo,
	options: AnswerOptions,
): Promise<AnswerEvent | undefined> {
	const { gh, log } = options;
	const reply = readAnswerReply(info.triggerText);
	const replyId = info.commentId;
	if (reply === undefined || replyId === undefined) {
		return undefined;
	}
	if (
		!validatePermissions(info.author, info.authorAssociation, options.allow)
	) {
		log.warning(
			`Ignoring /answer from @${info.author.login}, who is not allowed to run pi`,
		);
		return undefined;
	}
	const found = questionFor(
		await gh.listIssueComments(info.issueNumber),
		replyId,
		reply.quote,
	);
	if (!found) {
		log.info("An /answer reply, but no question is waiting for one; skipping");
		return undefined;
	}
	const { comment, question } = found;
	const { login } = info.author;
	log.info(
		`@${login} answered ${oneLine(question.title)} (${comment.html_url})`,
	);
	await Promise.all([
		settle(
			gh,
			{ id: comment.id, body: comment.body ?? "" },
			reply.text,
			login,
			log,
		),
		thumbsUp(gh, info.issueNumber, replyId, log),
	]);
	return answerTrigger(
		info,
		{
			key: question.key,
			kind: question.kind,
			answer: reply.text,
			by: login,
			url: comment.html_url,
			title: question.title,
		},
		reply.text,
		{
			author: info.author,
			commentId: replyId,
			questionId: comment.id,
			createdAt: info.createdAt ?? new Date().toISOString(),
		},
	);
}

/**
 * The answer the event carries, after checking who gave it, with the question marked answered (and the reply 👍).
 * Undefined, with the reason in the log, when the event is not a valid new answer.
 */
export async function answerFromEvent(
	payload: Record<string, unknown>,
	options: AnswerOptions,
): Promise<AnswerEvent | undefined> {
	const kind = questionEventKind(payload);
	const info = kind ? extractTriggerInfo(payload) : null;
	if (!(kind && info)) {
		return undefined;
	}
	return kind === "edit"
		? fromEdit(payload, info, options)
		: fromReply(info, options);
}
